#include "stdafx.h"#include "HcdRsu.h"BYTE* KHcdRsu::RegisterPageConnector( LPCSTR pszName, eHcdVType **ppType ){  SPageConnector *pCur = NULL;  if( !m_pFirstPageCon )  {    pCur = m_pLastPageCon = m_pFirstPageCon = new SPageConnector;    strcpy_s( pCur->szName, pszName );    pCur->type = **ppType;    *ppType = &pCur->type;    ++m_nPageCons;  }  else  {    for( pCur=m_pFirstPageCon; pCur; pCur = pCur->pNext )    {      if( !strcmp( pCur->szName, pszName) )      {        *ppType = &pCur->type;        return (BYTE*)&pCur->ana;      }    }    pCur = new SPageConnector;    strcpy_s( pCur->szName, pszName );    pCur->type = **ppType;    *ppType = &pCur->type;    m_pLastPageCon->pNext = pCur;    m_pLastPageCon = pCur;    ++m_nPageCons;  }  return (BYTE*)&pCur->ana;}int KHcdRsu::StepCalc( tAnalog32 dtS, tDigital32 dtMs ){  m_params.dtS = dtS;  m_params.nStep++;  m_params.pszObjName = m_szObjName;  if( m_pHcdSystem )    m_params.modelTime = m_pHcdSystem->TimeM();   for( DWORD n=0; n<m_nSheets; ++n )    m_pSheets[n].StepCalc( m_params );  return 0;}void KHcdRsu::RegisterVar( IHcdElement *pSingleVar ){  SVariable *pCur = NULL;  if( !m_pFirstVariable )  {    pCur = m_pLastVariable = m_pFirstVariable = new SVariable;    strcpy_s( pCur->szName, pSingleVar->szName );    pCur->pVar = pSingleVar;    ++m_nVariables;    return;  }  for( pCur=m_pFirstVariable; pCur; pCur = pCur->pNext )  {    if( !strcmp( pCur->szName, pSingleVar->szName) )    {      return;    }  }  pCur = new SVariable;  strcpy_s( pCur->szName, pSingleVar->szName );  pCur->pVar = pSingleVar;  m_pLastVariable->pNext = pCur;  m_pLastVariable = pCur;  ++m_nVariables;}BYTE* KHcdRsu::GetVarPV( LPCSTR pszName, eHcdVType *pType ){  for( SVariable *pCur=m_pFirstVariable; pCur; pCur = pCur->pNext )  {    if( strcmp(pCur->szName, pszName) )      continue;    return pCur->pVar->GetField( "PV", pType );  }  return NULL;}